import{_ as l,o as a,c as d,a2 as o}from"./chunks/framework.DxR7mb1F.js";const h=JSON.parse('{"title":"WorkBuddy 阅读与学习指南｜从入门到团队落地","titleTemplate":false,"description":"WorkBuddy 中文学习指南与阅读路线，从下载安装、第一个任务和 Skill 入门，到真实案例、自动化、多 Agent 系统与团队落地。","frontmatter":{"title":"WorkBuddy 阅读与学习指南｜从入门到团队落地","titleTemplate":false,"description":"WorkBuddy 中文学习指南与阅读路线，从下载安装、第一个任务和 Skill 入门，到真实案例、自动化、多 Agent 系统与团队落地。","breadcrumbTitle":"阅读指南"},"headers":[],"relativePath":"reading-guide.md","filePath":"reading-guide.md","lastUpdated":1786808975000}'),i={name:"reading-guide.md"};function r(t,e,u,k,n,b){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="workbuddy-阅读与学习指南-从入门到团队落地" tabindex="-1">WorkBuddy 阅读与学习指南：从入门到团队落地 <a class="header-anchor" href="#workbuddy-阅读与学习指南-从入门到团队落地" aria-label="Permalink to &quot;WorkBuddy 阅读与学习指南：从入门到团队落地&quot;">​</a></h1><p>这是一条面向新手、任务实践者和团队负责人的 WorkBuddy 学习路线。你不必从头背功能：先找到当前最接近的工作问题，完成一项真实任务，再沿着使用手册、实战案例、进阶系统和团队落地逐步深入。</p><h2 id="workbuddy-新手入门路线" tabindex="-1">WorkBuddy 新手入门路线 <a class="header-anchor" href="#workbuddy-新手入门路线" aria-label="Permalink to &quot;WorkBuddy 新手入门路线&quot;">​</a></h2><p>从<a href="/bluebook/bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/">第一篇：先把 WorkBuddy 用起来</a>开始，依次完成：</p><ol><li>下载、安装和登录。</li><li>认识主界面、任务与工作区。</li><li>完成第一个可检查的任务。</li><li>加载一个真正用得上的 Skill。</li><li>再学习连接器、外部 API 与自动化任务。</li></ol><p>建议边读边做，不要只浏览截图。每完成一章，至少留下一个可复用的提示词、模板或操作记录。</p><h2 id="按真实任务选择-workbuddy-教程" tabindex="-1">按真实任务选择 WorkBuddy 教程 <a class="header-anchor" href="#按真实任务选择-workbuddy-教程" aria-label="Permalink to &quot;按真实任务选择 WorkBuddy 教程&quot;">​</a></h2><p>直接进入<a href="/bluebook/bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/">第二篇：案例篇</a>，按问题选择章节：</p><ul><li>处理 Word、Excel、PPT：第 11 章。</li><li>整理电脑文件：第 12 章。</li><li>远程控制电脑：第 13 章。</li><li>资讯、收藏、会议和投资：第 15～18 章。</li><li>AI 视频、自媒体和 GEO：第 19～21 章。</li></ul><p>案例跑通后，再回到第三篇，把你的做法整理为 Skill、自动化或多 Agent 系统。</p><h2 id="workbuddy-团队落地路线" tabindex="-1">WorkBuddy 团队落地路线 <a class="header-anchor" href="#workbuddy-团队落地路线" aria-label="Permalink to &quot;WorkBuddy 团队落地路线&quot;">​</a></h2><p>重点阅读<a href="/bluebook/bluebook/第三篇 进阶篇：把案例变成自己的工作系统/">第三篇：进阶篇</a>与<a href="/bluebook/bluebook/第四篇 岗位与行业落地/">第四篇：岗位与行业落地</a>。</p><p>团队实践建议同时记录：</p><ul><li>输入资料和权限边界。</li><li>任务拆解方式和失败回退。</li><li>交付物的验收标准。</li><li>可以复用的 Skill、模板和自动化。</li><li>哪些步骤必须由人确认。</li></ul><h2 id="发现内容可以改进" tabindex="-1">发现内容可以改进 <a class="header-anchor" href="#发现内容可以改进" aria-label="Permalink to &quot;发现内容可以改进&quot;">​</a></h2><p>欢迎阅读<a href="/bluebook/community/contributing">参与共创</a>，通过 Issue 提出问题，或直接提交 Pull Request 修改对应 Markdown 页面。</p>',16)])])}const p=l(i,[["render",r]]);export{h as __pageData,p as default};
